async(page)=>{
 const click=async a=>page.locator(`[data-action=${a}]`).first().click();const submit=async()=>{await page.locator('#action-form [type=submit]').click();await page.locator('#dialog').waitFor({state:'hidden'})};
 await page.goto('http://127.0.0.1:4173/prototype/#dispatch');await page.reload();await page.setViewportSize({width:1440,height:1000});
 if(await page.locator('[data-dispatch-tab][aria-selected=true]').getAttribute('data-dispatch-tab')!=='map')throw Error('map not default');
 await click('qa');await click('reset');await submit();await page.locator('[data-role=dispatch]').first().click();
 await page.locator('[data-fleet=V02]').click();await page.locator('#map-order-selector').selectOption('RF-1024-001');await click('fleet-assign');if(!await page.locator('[name=vehicle][value=V02]').isChecked())throw Error('vehicle preselection failed');await submit();
 const db=()=>page.evaluate(()=>JSON.parse(sessionStorage.getItem('routefit-r1-prototype-v1')));if((await db()).orders[0].vehicle!=='V02')throw Error('dispatch failed');await click('revoke');await submit();
 await click('busy-scenario');await page.locator('[data-fleet=V01]').click();if(!await page.locator('[data-action=authorizeReturn]').count())throw Error('vehicle task action absent');await click('authorizeReturn');await page.locator('[name=reason]').fill('演示：在地图调度面板核对回仓地点、容量和时间');await submit();if(!(await db()).orders.find(o=>o.id==='RF-DEMO-204').returnAuthorized)throw Error('map action not recorded');
 await page.locator('[data-dispatch-tab=orders]').click();if(!await page.locator('#search').isVisible())throw Error('queue absent');if(await page.locator('.order-expand').getAttribute('open')!==null)throw Error('details not collapsed');
 await page.locator('[data-dispatch-tab=alerts]').click();if(!await page.locator('.dispatch-alerts').isVisible())throw Error('alerts absent');if(await page.locator('.dispatch-summary').isVisible())throw Error('overview mixed in alerts');await page.locator('[data-alert-order="RF-DEMO-201"]').first().click();if(await page.locator('[data-dispatch-tab=orders]').getAttribute('aria-selected')!=='true')throw Error('alert drill through failed');
 await page.locator('[data-dispatch-tab=overview]').click();if(await page.locator('.dispatch-alerts').isVisible())throw Error('alerts mixed in overview');await page.locator('[data-stage=in_transit]').click();if(!(await page.locator('tbody').innerText()).includes('RF-DEMO-203'))throw Error('overview filter failed');
 await page.locator('[data-dispatch-tab=map]').click();await page.keyboard.press('ArrowRight');if(await page.locator('[data-dispatch-tab=orders]').getAttribute('aria-selected')!=='true')throw Error('keyboard tabs failed');await page.keyboard.press('Home');
 const before=await page.locator('.fleet-map-plane').getAttribute('style');await click('fleet-zoom-in');if(await page.locator('.fleet-map-plane').getAttribute('style')===before)throw Error('zoom failed');await click('fleet-center');await page.waitForTimeout(4600);await page.screenshot({path:'E:/Dr.RouteFit/prototype/screenshots/dispatch-map-tabs.png',fullPage:true});
 for(const width of [1280,390]){await page.setViewportSize({width,height:900});if(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth))throw Error('overflow '+width)}await page.setViewportSize({width:1440,height:1000});
 return {status:'PASS',checks:['default bounded map','map vehicle preselected dispatch and revoke','vehicle associated return authorization','independent tabs and collapsed detail','alert and stage drill through','keyboard tabs','zoom / show all','1280 / 390 responsive']};
}
